$q=trim($_GET['q']??'');$status=$_GET['status']??'';$vendor=(int)($_GET['vendor_id']??0);$where=['vi.company_id=?'];$args=[$companyId]; if($q!==''){$where[]='(vi.invoice_number LIKE ? OR v.vendor_name LIKE ? OR vi.order_number LIKE ?)';$like='%'.$q.'%';array_push($args,$like,$like,$like);} if($status!==''){$where[]='vi.status=?';$args[]=$status;} if($vendor>0){$where[]='vi.vendor_id=?';$args[]=$vendor;}
$stmt=$conn->prepare("SELECT vi.*,v.vendor_name,
(SELECT COUNT(*) FROM re_vendor_bill_attachments a WHERE a.vendor_invoice_id=vi.id AND a.company_id=vi.company_id) attachment_count,
(SELECT jh.id FROM re_journal_headers jh WHERE jh.company_id=vi.company_id AND jh.reference_type='vendor_invoice' AND jh.reference_id=vi.id AND jh.is_posted=1 AND jh.is_reversed=0 ORDER BY jh.id DESC LIMIT 1) posted_journal_id,
COALESCE((SELECT SUM(l.vat_amount_linked) FROM re_vendor_advance_vat_bill_links l WHERE l.company_id=vi.company_id AND l.vendor_invoice_id=vi.id AND l.status='posted'),0) AS linked_advance_vat
FROM re_vendor_invoices vi JOIN re_vendors v ON v.id=vi.vendor_id AND v.company_id=vi.company_id WHERE ".implode(' AND ',$where)." ORDER BY vi.invoice_date DESC,vi.id DESC LIMIT 500");$stmt->execute($args);$bills=$stmt->fetchAll(PDO::FETCH_ASSOC)?:[];$vendors=$conn->prepare("SELECT id,vendor_name FROM re_vendors WHERE company_id=? AND status='active' ORDER BY vendor_name");$vendors->execute([$companyId]);$vendors=$vendors->fetchAll(PDO::FETCH_ASSOC)?:[];
