<div class="card card-round mb-4"><div class="card-body"><form class="row g-2"><div class="col-md-3"><input name="q" class="form-control" value="<?=h($q)?>" placeholder="Search bill/vendor/order"></div><div class="col-md-3"><select name="vendor_id" class="form-select"><option value="0">All vendors</option><?php foreach($vendors as $v): ?><option value="<?=$v['id']?>" <?=$vendor===$v['id']?'selected':''?>><?=h($v['vendor_name'])?></option><?php endforeach; ?></select></div><div class="col-md-3"><select name="status" class="form-select"><option value="">All statuses</option><?php foreach(['draft','open','partially_paid','paid','void','pending','approved','cancelled'] as $s): ?><option value="<?=$s?>" <?=$status===$s?'selected':''?>><?=h(ucwords(str_replace('_',' ',$s)))?></option><?php endforeach; ?></select></div><div class="col-md-3"><button class="btn btn-primary w-100">Filter</button></div></form></div></div>
<div class="card card-round"><div class="table-responsive"><table class="table table-hover mb-0"><thead class="table-light"><tr><th>Bill #</th><th>Vendor</th><th>Bill Date</th><th>Due Date</th><th class="text-end">Total</th><th class="text-end">Paid</th><th class="text-end">Balance</th><th>Status</th><th>GL</th><th>Attachments</th><th>Actions</th></tr></thead><tbody><?php foreach($bills as $b): ?><?php $cashPaid=(float)($b['paid_amount']??0); $linkedVat=(float)($b['linked_advance_vat']??0); $paid=round($cashPaid+$linkedVat,2); /* balance_due is authoritative (0 is valid after linked advance VAT) */ $bal=(float)($b['balance_due']??max(0,(float)$b['total_amount']-$paid)); $postedJournalId=(int)($b['journal_id'] ?: ($b['posted_journal_id'] ?? 0)); $isPosted=(($b['posting_status']??'not_posted')==='posted'||$postedJournalId>0); ?><tr><td><strong><?=h($b['invoice_number'])?></strong><br><small><?=h($b['order_number']?:'')?></small></td><td><?=h($b['vendor_name'])?></td><td><?=h($b['invoice_date'])?></td><td><?=h($b['due_date'])?></td><td class="text-end"><?=m($b['total_amount'])?></td><td class="text-end"><?=m($paid)?><?php if($linkedVat>0.005): ?><br><small class="text-muted">incl. adv VAT <?=m($linkedVat)?></small><?php endif; ?></td><td class="text-end <?= $bal>0.005?'text-danger':'text-success' ?>"><?=m($bal)?></td><td><span class="badge bg-<?= in_array($b['status'],['paid'],true)?'success':(in_array($b['status'],['draft'],true)?'warning text-dark':($b['status']==='void'||$b['status']==='cancelled'?'secondary':'primary')) ?>"><?=h($b['status'])?></span></td><td><?php if($isPosted): ?><span class="badge bg-success">Posted</span><?php else: ?><form method="post"><?php csrf_field(); ?><input type="hidden" name="action" value="post_to_gl"><input type="hidden" name="vendor_invoice_id" value="<?=$b['id']?>"><button class="btn btn-sm btn-outline-primary">Post</button></form><?php endif; ?></td><td><?= (int)($b['attachment_count']??0) ?></td><td class="d-flex flex-wrap gap-1">
<a href="vendor_bill_view.php?id=<?=$b['id']?>" class="btn btn-sm btn-primary">View</a>
<a href="vendor_bill_edit.php?id=<?=$b['id']?>" class="btn btn-sm btn-outline-primary">Edit</a>
<?php if($isPosted&&$cashPaid<=0.005&&!in_array($b['status'],['void','cancelled','paid'],true)): ?><a href="vendor_bill_view.php?id=<?=$b['id']?>" class="btn btn-sm btn-outline-warning">Void/Amend</a><?php endif; ?>
<?php if($bal>0&&$isPosted): ?><a href="vendor_payment_add.php?vendor_id=<?=$b['vendor_id']?>&bill_id=<?=$b['id']?>" class="btn btn-sm btn-success">Pay</a><?php endif; ?>
<a href="vendor_bill_view.php?id=<?=$b['id']?>&print=1" class="btn btn-sm btn-outline-dark" target="_blank">Print</a>
<a href="vendor_recurring_bills.php?action=create&source_bill_id=<?=$b['id']?>" class="btn btn-sm btn-outline-info">Recurring</a>
